export const L=pair;
export function executionActionError(error){
 const operational={'请先恢复交易账户、研究数据和 AI 模型连接。':'Reconnect the trading account, research data and AI model.','资金保护设置已变化，请重新检查策略设置。':'Capital protection changed. Review the strategy settings.','已达到当前资金保护上限，请先检查资金保护。':'The capital protection limit was reached. Review protection.','运行已结束或由你接管，请在新方案中重新确认交易范围。':'This run ended or is under manual control. Confirm trading scope in a new plan.','运行已结束或由你接管，不再新增交易。':'This run ended or is under manual control. No new trades will open.','请选择保留持仓或退出持仓。':'Choose whether to keep or exit the position.','运行身份缺失，不能提交退出。':'The run identity is missing. The exit was not submitted.','运行或账户已变化，请重新打开运行后再操作。':'Run or account changed. Reopen the run before acting.'};
 if(operational[error])return L(error,operational[error]);
 if(error==='这份入场方案已变化或失效，请查看最新方案。')return L('这份入场方案已变化或失效，请查看最新方案。','This entry plan changed or expired. Review the latest plan.');
 if(error==='这次入场需要先批准当前方案。')return L('这次入场需要先批准当前方案。','Approve the current plan before this entry.');
 if(error==='研究、连接或资金保护已变化，请重新检查方案。')return L('研究、连接或资金保护已变化，请重新检查方案。','Research, access or protection changed. Review the plan again.');
 if(error==='原操作仍待核对；查询未生成新委托，资金占用保留。')return L('原订单仍未确认，资金继续暂占。请稍后再查询，不要重复下单。','The original order is unconfirmed. Funds remain held. Check again later; do not resubmit.');
 if(error==='回执未知，先模拟对账再撤销，不能直接当成零成交。')return L('这笔订单还未确认。请先查询结果，再取消未成交的部分。','This order is unconfirmed. Check its result before cancelling the unfilled remainder.');
 return friendlyText(error);
}
export function executionActionFeedback(action,before,after){
 const orderId=(['reconcile','cancel'].includes(action)?before.pending?.id:null)||after.pending?.id||before.pending?.id;
 if(action==='stop'&&after.pending)return {message:after.pending.status==='unknown'?L('已停止新增交易，原订单结果仍待确认。','New entries stopped. The original order remains unconfirmed.'):after.pending.intent==='close'||!after.pending.intent&&after.pending.side==='sell'?L('已停止新增交易，退出订单正在处理。','New entries stopped. The exit order is processing.'):L('已停止新增交易，原订单仍在处理中。','New entries stopped. The original order is still processing.'),tone:'info',orderId};
 if(action==='stop'&&after.session?.endIntent==='close'&&after.position)return {message:L('退出尚未完成，已有持仓仍保留。','Exit is incomplete. A position remains.'),tone:'error',orderId:after.orders?.[0]?.id};
 if(action==='confirm'||action==='approve'||action==='close')return after.pending?{message:L('订单已提交，正在等成交结果。','Order submitted. Waiting for fill confirmation.'),tone:'info',orderId}:null;
 if(action==='pause'&&after.state==='paused')return {message:after.pending?after.pending.status==='unknown'?L('已暂停新增交易，原订单仍待确认。','New entries paused. The existing order remains unconfirmed.'):L('已暂停新增交易，原订单继续处理。','New entries paused. The existing order is still processing.'):after.position?L('已暂停新增交易，已有持仓保留。','New entries paused. Your position remains open.'):L('已暂停新增交易。','New entries paused.'),tone:'success',orderId};
 if(action==='stop'&&after.state==='stopped')return {message:after.position?L('策略已停止，已有持仓保留。','Strategy stopped. Your position remains open.'):L('策略已停止，没有持仓。','Strategy stopped. No open position.'),tone:'success'};
 if(action==='resume'&&after.state==='running')return {message:after.session?.awaitingResearch?L('策略已继续，正在等待交易条件。','Strategy resumed and waiting for entry conditions.'):L('策略已继续，金额与资金保护保持不变。','Strategy resumed with the same amounts and protection.'),tone:'success'};
 if(action==='cancel'&&before.pending&&!after.pending)return {message:L('未成交的剩余数量已撤销，已成交部分保留。','Unfilled remainder cancelled. Confirmed fills are retained.'),tone:'success',orderId};
 if(action==='reconcile'){
  if(after.pending?.id===orderId)return {message:after.pending.status==='unknown'?L('原订单仍在等待确认，请勿重复提交。','The original order is still unconfirmed. Do not resubmit.'):L('已找到原订单，继续等待原订单的成交结果。','Original order found. Waiting for its fill results.'),tone:'info',orderId};
  const order=after.orders?.find(item=>item.id===orderId),outcomes={filled:[L('原订单已成交，请查看持仓与成交记录。','The original order filled. Review the position and fills.'),'success'],cancelled:[L('原订单已撤销。','The original order was cancelled.'),'success'],'partial-cancelled':[L('原订单的剩余数量已撤销，已成交部分保留。','The remaining quantity was cancelled. Confirmed fills are retained.'),'success'],rejected:[L('原订单未成交，请查看订单记录。','The original order was rejected. Review the order record.'),'error']},outcome=outcomes[order?.status];
  return {message:outcome?.[0]||L('请查看原订单记录，确认最终结果。','Review the original order record to confirm its final result.'),tone:outcome?.[1]||'info',orderId};
 }
 if(action==='deliver-receipt')return {message:L('模拟回报已送达，请再查询原交易结果。','The simulated response is ready. Check the original trade result again.'),tone:'info',orderId};
 if(action==='skip'&&before.signal&&!after.signal)return {message:L('已跳过这次信号，没有新增订单。','Signal skipped. No new order was created.'),tone:'success'};
 if(action==='read')return {message:L('通知已标记为已读。','Notifications marked as read.'),tone:'success'};
 return null;
}
export function canReviewResearchChange(data){
 // shortcut: the simulator has no reason code; require its latest exact cause until the execution adapter supplies one.
 return Boolean(data?.state==='blocked'&&data.session&&data.session.mode!=='confirm'&&!data.session.singleShot&&!data.pending&&!data.position&&data.events?.[0]?.text?.startsWith('研究版本已变化'));
}
