export function executionCreditView(data,credits){
 const session=data?.session;if(!session||!credits)return '';
 const startup=credits.startup?.id===session.usageId?credits.startup:null,tasks=Array.isArray(credits.tasks)?credits.tasks:[];
 const taskId=startup?.membershipTaskId,task=taskId?tasks.find(job=>job.id===taskId):null;
 const related=tasks.some(job=>job.input?.runId===session.id&&(!job.input.accountId||job.input.accountId===(session.accountId||session.ticket?.accountId||'SIM-01')));
 const href=taskId?commerceContextLink({taskId},'usage'):related?commerceContextLink({runId:session.id},'usage'):null,summary=taskCreditSummary(task);
 const legacy=!taskId&&!related&&Number.isFinite(credits.start)&&credits.start>=0;
 const title=href?L('当前运行费用','Run charges'):legacy?L('历史启动记录','Legacy launch record'):L('费用记录','Charge records');
 const value=href?(summary?(summary.pending?L('结算中','Settlement pending'):amount(summary.settled)+' Credit'):'—'):legacy?amount(credits.start)+' '+L('AI 积分','AI credits'):'—';
 return `<section class="execution-followup"><span>${title} <b>${value}</b>${legacy?` <small>${esc(startup?.priceVersion||L('旧版模拟','Legacy simulation'))}</small>`:''}</span><div>${action(L('资产与费用','Assets & costs'),'go','assets')}${href?`<a class="p-button" data-commerce-context href="${esc(href)}">${L('费用明细','Charge details')}</a>`:action(L('全部用量','All usage'),'go','usage')}</div></section>`;
}
