export function patchExecutionPrices(root,data,status){
 const run=executionRunIdentity(data,status?.scope),view=root.querySelector('.contract-run[data-run]');
 if(!run||!view||status?.scope&&(run.accountId!==status.scope.accountId||run.environment!==status.scope.environment)||view.dataset.run!==run.runId||view.dataset.runAccount!==run.accountId||view.dataset.runEnvironment!==run.environment||(view.dataset.runConnection||'')!==(run.connectionId||'')||(view.dataset.runInstrument||'')!==(run.instrumentId||''))return false;
 const p=scopeExecutionRecords(data,run).position;if(!p)return false;
 const mark=p.markPrice??p.price,pnl=isPerp(p)?positionPnl(p):(mark-p.price)*p.qty,currency=p.currency||orderMarket(p)?.currency||'USDT';
 if(!Number.isFinite(mark)||mark<=0||!Number.isFinite(pnl))return false;
 const markNode=root.querySelector('[data-exec-mark]'),pnlNode=root.querySelector('[data-exec-pnl]');
 if(markNode)markNode.textContent=price(mark)+' '+currency;
 if(pnlNode){pnlNode.textContent=(pnl>0?'+':'')+Number(pnl).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})+' '+currency;pnlNode.className=pnl<0?'execution-negative':'execution-positive';}
 return Boolean(markNode||pnlNode);
}
