 return `<p class="execution-manager-basis">${L('币安现货 BTC/USDT。撤销只取消这一笔挂单，不会新开订单。','Binance spot BTC/USDT. Cancel removes that resting order and does not place a new one.')}</p>${table('当前委托',book.orders,'当前没有挂单')}${table('历史委托',book.history,'还没有历史订单')}`;
