export function spotAccountFigures(book){
 if(!book||book.symbol!=='BTCUSDT')return null;
 const free=Number(book.usdt),locked=Number(book.usdtLocked),btc=Number(book.btc);
 if(![free,locked,btc].every(value=>Number.isFinite(value)&&value>=0&&value<=1e15))return null;
 const price=Number(book.btcPrice),held=Number.isFinite(price)&&price>0&&price<=1e15?btc*price:null;
 return {equity:free+locked+(held??0),freeCash:free,reservedCash:locked,held:held??0,btc,priced:held!==null};
}
